#include <deque>
#include <iostream>

int main() {
    std::deque<int> d1 = {1, 2, 3};
    std::deque<int> d2 = {1, 2, 3};
    std::deque<int> d3 = {1, 2, 4};
    std::deque<int> d4 = {1, 2};

    std::cout << "d1 == d2: " << (d1 == d2) << " (True)" << std::endl;
    std::cout << "d1 < d3: " << (d1 < d3) << " (True, 3 < 4)" << std::endl;
    std::cout << "d4 < d1: " << (d4 < d1) << " (True, d4 is shorter)" << std::endl;

    // Element requirement failure (if Elem lacked operator<)
    // std::deque<MyType> d5; // Fails compilation if MyType not comparable
}
